+  }
+
+  if (stagnant_steps >= 2) {
+    if (stagnant_steps == 2) {
+      return SearchRepairArgs{9, -(it % 9), 8, 32 * shapeCost, 8 * markerCost, 32 * shapeCost, 0.990f, RipUpMode::NEARDRC, false};
+    }
